<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { api } from './services/api'

type DocumentRow = { id: string; resourceId?: string; title: string; type: string; status: string; author: string; version: string; updated: string }
const documents = ref<DocumentRow[]>([{ id: 'doc-design', title: 'Ikaros V2 产品设计', type: '文档', status: '草稿', author: '陈昊', version: 'v12', updated: '昨天 18:24' }, { id: 'doc-api', title: 'API 契约备忘', type: '文章', status: '已发布', author: '陈昊', version: 'v4', updated: '3 天前' }, { id: 'doc-release', title: '发布说明', type: '文档', status: '已归档', author: '团队', version: 'v2', updated: '5 天前' }]); const selectedId = ref<string | null>(null); const query = ref(''); const status = ref('全部'); const editorTitle = ref(''); const editorContent = ref(''); const saving = ref(false); const saved = ref(false); const publishConfirm = ref(false); const toast = ref(''); let saveTimer: number | undefined
const selected = computed(() => documents.value.find(item => item.id === selectedId.value)); const filtered = computed(() => documents.value.filter(item => `${item.title} ${item.type} ${item.author}`.toLowerCase().includes(query.value.toLowerCase()) && (status.value === '全部' || item.status === status.value)))
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
const actorId = String(import.meta.env.VITE_ACTOR_ID || '')
async function loadDocuments() { if (!actorId) return; try { const result = await api.listDocuments(actorId); if (result.length) documents.value = result.map(item => ({ id: item.id, resourceId: item.resourceId || item.resource_id, title: `Document ${item.id.slice(0, 8)}`, type: item.kind === 'ARTICLE' ? '文章' : item.kind === 'NOTE' ? '笔记' : '文档', status: item.currentRevisionId || item.current_revision_id ? '草稿' : '未开始', author: '当前用户', version: item.currentRevisionId || item.current_revision_id ? '已创建版本' : 'v1', updated: '刚刚' })) } catch { notify('文档 API 暂不可用，已保留演示数据') } }
async function hydrateDocumentTitles() { if (!actorId) return; await Promise.all(documents.value.filter(item => item.resourceId).map(async item => { try { const resource = await api.getResource(item.resourceId!); if (resource.title) item.title = resource.title } catch { /* 无资源读取权限时保持脱敏 ID */ } })) }
function openDocument(item: DocumentRow) { if (!documents.value.some(document => document.id === item.id)) documents.value.unshift(item); selectedId.value = item.id; editorTitle.value = item.title; editorContent.value = item.id === 'doc-design' ? '记录产品决策、领域边界与实现约束。\n\n## 下一步\n- 完成权限审阅\n- 验证后台任务流程' : '在这里开始编辑文档内容…'; saved.value = true }
function scheduleSave() { saved.value = false; saving.value = true; if (saveTimer) window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => { saving.value = false; saved.value = true; notify('草稿已自动保存') }, 650) }
function saveNow() { scheduleSave(); notify('正在保存草稿') }
function publish() { const item = selected.value; if (!item) return; item.status = '已发布'; item.title = editorTitle.value || item.title; item.updated = '刚刚'; publishConfirm.value = false; saved.value = true; notify('文档已发布并写入审计') }
watch([editorTitle, editorContent], () => { if (selectedId.value) scheduleSave() }); onBeforeUnmount(() => { if (saveTimer) window.clearTimeout(saveTimer) }); loadDocuments().then(hydrateDocumentTitles)
</script>

<template><div class="document-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">内容与创作 · 文章与文档</span><span class="mini-avatar">陈</span></header><main class="document-main"><section v-if="!selectedId" class="document-list-view"><div class="catalog-heading"><div><p class="eyebrow">内容与创作</p><h1>文章与文档</h1><p>管理草稿、发布版本与归档内容。</p></div><button class="filled-button" @click="openDocument({ id: `new-${Date.now()}`, title: '未命名文档', type: '文档', status: '草稿', author: '陈昊', version: 'v1', updated: '刚刚' })">＋ 新建</button></div><div class="document-toolbar surface-card"><div class="search-inline"><span>⌕</span><input v-model="query" placeholder="搜索标题或作者" /></div><div class="filter-row"><button v-for="value in ['全部','草稿','已发布','已归档']" :key="value" class="filter-chip" :class="{ active: status === value }" @click="status = value">{{ value }}</button></div></div><section class="document-table surface-card"><table><thead><tr><th>标题</th><th>类型</th><th>状态</th><th>作者</th><th>版本</th><th>最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id" @click="openDocument(item)"><td><b>{{ item.title }}</b></td><td>{{ item.type }}</td><td><span class="status-chip" :class="item.status === '草稿' ? 'warning' : item.status === '已归档' ? 'neutral' : 'success'">● {{ item.status }}</span></td><td>{{ item.author }}</td><td>{{ item.version }}</td><td class="muted-text">{{ item.updated }}</td><td><button class="text-button" @click.stop="openDocument(item)">编辑 →</button></td></tr></tbody></table><div v-if="filtered.length === 0" class="no-results">没有匹配文档</div></section></section><section v-else class="editor-view"><div class="editor-top"><button class="text-button" @click="selectedId = null">← 返回列表</button><div class="editor-save-state"><span :class="{ saving }">{{ saving ? '正在保存…' : saved ? '已保存' : '离线修改' }}</span><button class="outlined-button small" @click="saveNow">⌘ S 保存</button><button class="outlined-button small" @click="publishConfirm = true">发布</button></div></div><div class="editor-layout"><article class="editor-canvas surface-card"><input v-model="editorTitle" class="editor-title-input" placeholder="未命名文档" /><div class="editor-toolbar"><button>粗体</button><button>斜体</button><button>链接</button><span></span><button>Markdown</button></div><textarea v-model="editorContent" class="editor-content" placeholder="开始写作…"></textarea></article><aside class="editor-sidebar surface-card"><h2>文档属性</h2><label>内容类型<select><option>文档</option><option>文章</option></select></label><label>状态<select v-model="selected!.status"><option>草稿</option><option>已发布</option><option>已归档</option></select></label><label>Slug / 公开标识<input placeholder="可选" /></label><div class="editor-note"><span>i</span><p>编辑器变更会自动保存为新版本；发布前会明确可见性与发布时间。</p></div></aside></div></section></main><div v-if="publishConfirm" class="role-create-scrim" @click.self="publishConfirm = false"><section class="role-create-dialog"><div class="dialog-title"><div><p class="eyebrow">发布确认</p><h2>发布此文档？</h2></div><button class="icon-button" @click="publishConfirm = false">×</button></div><p class="review-copy">发布后当前版本将对授权读者可见，历史版本不会被删除。</p><div class="dialog-actions"><button class="outlined-button" @click="publishConfirm = false">取消</button><button class="filled-button" @click="publish">确认发布</button></div></section></div><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
